using namespace std;
typedef long long int ll;
typedef pair<int, int> P;
vector<ll> v;
void dfs(int k, ll x){
	v.push_back(x);
	if(k>=9) return;
	int a=x%10;
	if(a){
		dfs(k+1, x*10+a-1);
	}
	dfs(k+1, x*10+a);
	if(a<9){
		dfs(k+1, x*10+a+1);
	}
}
int main()
{
	for(int i=1; i<=9; i++) dfs(0, i);
	sort(v.begin(), v.end());
	v.erase(unique(v.begin(), v.end()), v.end());
	int k; cin>>k;
	cout<<v[k-1]<<endl;
	return 0;
}
